import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Sidebar from "./components/Sidebar";
import ProductForm from "./components/product/ProductForm";
import ProductList from "./components/product/ProductList";
import EmployeeForm from "./components/employee/EmployeeForm";
import EmployeeList from "./components/employee/EmployeeList";
import UserForm from "./components/user/UserForm";
import UserList from "./components/user/UserList";
import Layout from "./components/layout";
import Login from "./components/login/Login";
import ProtectedRoute from "./components/login/ProtectedRoute";
import AdminRoute from "./components/login/AdminRoute";
import { useEffect } from "react";
import { setAuthToken } from "./redux/root/api";

function App() {
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) setAuthToken(token);
  }, []);

  return (
    <Router>
      <Routes>
        {/* Public route */}
        <Route path="/login" element={<Login />} />

        {/* Protected routes with Layout */}
        <Route element={<ProtectedRoute />}>
          <Route element={<Layout />}>
            {/* Employee routes - accessible to all authenticated users */}
            <Route path="/" element={<EmployeeList />} />
            <Route path="/add" element={<EmployeeForm />} />
            <Route path="/edit/:id" element={<EmployeeForm />} />

            {/* Product routes - accessible to all authenticated users */}
            <Route path="/products" element={<ProductList />} />
            <Route path="/products/add" element={<ProductForm />} />

            {/* User routes - only accessible to ADMIN users */}
            <Route element={<AdminRoute />}>
              <Route path="/users" element={<UserList />} />
              <Route path="/users/add" element={<UserForm />} />
              <Route path="/users/edit/:id" element={<UserForm />} />
            </Route>
          </Route>
        </Route>
      </Routes>
    </Router>
  );
}

export default App;
